<script setup lang="ts">
import{ref,onMounted}from'vue';type Item=Record<string,any>;const bases=ref<Item[]>([]),docs=ref<Item[]>([]),versions=ref<Item[]>([]),kb=ref(0),doc=ref(0),oldId=ref(0),newId=ref(0),result=ref<Item|null>(null),busy=ref(false),error=ref('');const token=()=>sessionStorage.getItem('ops-token')||'';
async function api(path:string,options:RequestInit={}){const r=await fetch('/api'+path,{...options,headers:{Authorization:'Bearer '+token(),'Content-Type':'application/json'}}),b=await r.json();if(!r.ok)throw Error(b.message);return b.data}
async function loadDocs(){docs.value=await api('/knowledge-bases/'+kb.value+'/documents');doc.value=docs.value[0]?.id||0;await loadVersions()}async function loadVersions(){versions.value=doc.value?await api('/documents/'+doc.value+'/versions'):[];oldId.value=versions.value.at(-1)?.id||0;newId.value=versions.value[0]?.id||0;result.value=null}
async function compare(){busy.value=true;error.value='';try{result.value=await api('/admin/document-version-compare',{method:'POST',body:JSON.stringify({oldVersionId:oldId.value,newVersionId:newId.value})})}catch(e){error.value=e instanceof Error?e.message:'对比失败'}finally{busy.value=false}}
onMounted(async()=>{bases.value=await api('/knowledge-bases');kb.value=bases.value[0]?.id||0;if(kb.value)await loadDocs()});
</script>
<template><section><div class="assistant-head"><div><span class="eyebrow">VERSION INTELLIGENCE</span><h1>文档版本对比</h1><p class="muted">在本地识别正文变化并提示潜在风险，不将文档差异发送到外部模型。</p></div></div><div class="compare-toolbar"><label>知识库<select v-model="kb" @change="loadDocs"><option v-for="b in bases" :value="b.id">{{b.name}}</option></select></label><label>文档<select v-model="doc" @change="loadVersions"><option v-for="d in docs" :value="d.id">{{d.title}}</option></select></label><label>旧版本<select v-model="oldId"><option v-for="v in versions" :value="v.id">{{v.versionNo}}</option></select></label><span>→</span><label>新版本<select v-model="newId"><option v-for="v in versions" :value="v.id">{{v.versionNo}}</option></select></label><button :disabled="busy||!oldId||!newId||oldId===newId" @click="compare">{{busy?'正在比较…':'开始对比'}}</button></div><p v-if="error" class="banner error">{{error}}</p><div v-if="result" class="compare-result"><div class="compare-summary"><div><small>文档</small><strong>{{result.title}}</strong></div><div><small>版本路径</small><strong>{{result.oldVersion}} → {{result.newVersion}}</strong></div><div><small>新增</small><strong class="added">+{{result.added}}</strong></div><div><small>删除</small><strong class="deleted">-{{result.deleted}}</strong></div></div><section class="risk-panel"><h3>影响提示</h3><p v-for="h in result.riskHints">{{h}}</p></section><div class="diff-list"><article v-for="(c,i) in result.changes" :key="i" :class="c.type==='ADDED'?'diff-add':'diff-delete'"><span>{{c.type==='ADDED'?'+':'−'}} {{c.newLine||c.oldLine}}</span><pre>{{c.content}}</pre></article><p v-if="!result.changes.length" class="empty">两个版本正文一致</p></div></div><div v-else class="empty compare-empty"><div class="large-icon">⇄</div><h3>选择同一文档的两个版本</h3><p>对比结果保留原文，不使用生成式模型改写差异。</p></div></section></template>
